<script setup lang="ts">
import {computed,onMounted,onScopeDispose,ref} from 'vue'
import {useRouter} from 'vue-router'
import {message,Modal as AModal,Table as ATable,Progress as AProgress,Checkbox as ACheckbox,Collapse as ACollapse,Select as ASelect} from 'ant-design-vue'
import type {EChartsCoreOption} from 'echarts/core'
import StatePanel from '@starbeacon/shared/components/StatePanel.vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import {countText,percentage,severityName,type Bucket,type Distribution} from './overview'
import {useOverview} from './useOverview'
import OverviewChart from './OverviewChart.vue'
const props=withDefaults(defineProps<{screen?:boolean}>(),{screen:false})
const ACollapsePanel=ACollapse.Panel
const state=useOverview(),router=useRouter(),screenElement=ref<HTMLElement>(),{data,pending,error,hours,automatic}=state
const metrics=computed(()=>data.value?[{label:'已索引告警',value:data.value.events.total,tone:'blue',path:'/alerts'},{label:'登记资产',value:data.value.inventory.assets,tone:'violet',path:'/assets'},{label:'在线探针',value:data.value.inventory.online,tone:'green',path:'/sensors'},{label:'离线探针',value:data.value.inventory.offline,tone:'amber',path:'/sensors'}]:[])
const trend=computed<EChartsCoreOption>(()=>({grid:{left:50,right:12,top:18,bottom:45},xAxis:{type:'category',data:data.value?.events.trend.map(b=>new Date(b.key).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',timeZone:'UTC'}))??[],axisLabel:{hideOverlap:true}},yAxis:{type:'value',min:0,minInterval:1,name:'告警数'},series:[{type:'line',data:data.value?.events.trend.map(b=>Number(b.count))??[],showSymbol:false,lineStyle:{color:'#096bff',width:3},itemStyle:{color:'#096bff'},areaStyle:{color:'#096bff',opacity:0.08}}]}))
function rankOption(buckets:readonly Bucket[],color:string):EChartsCoreOption{return{grid:{left:100,right:24,top:12,bottom:28,containLabel:false},xAxis:{type:'value',min:0,minInterval:1},yAxis:{type:'category',inverse:true,data:buckets.map(b=>b.key),axisLabel:{width:85,overflow:'truncate'}},series:[{type:'bar',data:buckets.map(b=>Number(b.count)),itemStyle:{color,borderRadius:[0,3,3,0]},barMaxWidth:22}]}}
const protocolOption=computed(()=>rankOption(data.value?.events.protocols.buckets??[],'#0095ad'))
const ruleOption=computed(()=>rankOption(data.value?.events.rules.buckets??[],'#8950e9'))
const trendLabel=computed(()=>data.value?`已索引告警趋势，UTC ${data.value.window.start} 至 ${data.value.window.end}，${data.value.events.interval==='day'?'按天':'按小时'}汇总，共 ${data.value.events.total} 条告警。图形用于近似展示。`:'暂无告警趋势数据')
function distributionLabel(title:string,value:Distribution){return`${title}，${value.buckets.map(b=>`${b.key}：${b.count} 条`).join('；')}；其他：${value.other} 条；分布误差上界：${value.error_upper_bound} 条。`}
const detail=ref<Distribution|null>(null),detailTitle=ref('')
const isFullscreen=ref(false)
function updateFullscreen(){isFullscreen.value=!!document.fullscreenElement}
onMounted(()=>{updateFullscreen();document.addEventListener('fullscreenchange',updateFullscreen)})
onScopeDispose(()=>document.removeEventListener('fullscreenchange',updateFullscreen))
function show(title:string,value:Distribution){detailTitle.value=title;detail.value=value}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(screenElement.value?.requestFullscreen)await screenElement.value.requestFullscreen();else message.info('当前浏览器不支持全屏展示')}catch{message.error('无法切换全屏，请检查浏览器权限')}finally{updateFullscreen()}}
function alerts(){if(data.value)void router.push({path:'/alerts',query:{start:data.value.window.start,end:data.value.window.end}})}
</script>
<template>
 <main ref="screenElement" :class="['overview-workspace',{'overview-screen':props.screen}]">
  <header class="page-header"><div><h1>{{props.screen?'态势大屏':'态势总览'}}</h1><p class="page-description">汇总已索引告警、资产登记与探针状态，数据范围以实际观测为准。</p></div><div class="filter-actions"><a-select v-model:value="hours" aria-label="统计时间范围" :options="[{label:'最近 24 小时',value:24},{label:'最近 48 小时',value:48},{label:'最近 7 天',value:168},{label:'最近 30 天',value:720}]" @change="state.refresh"/><a-checkbox v-model:checked="automatic">自动刷新</a-checkbox><a-button :loading="pending" @click="state.refresh">刷新</a-button><a-button v-if="props.screen" :aria-pressed="isFullscreen" @click="fullscreen">{{isFullscreen?'退出全屏':'全屏展示'}}</a-button><a-button v-else @click="router.push('/screen')">态势大屏</a-button></div></header>
  <a-alert v-if="error&&data" type="error" :message="`${error}。下方为上次成功观测的数据。`" show-icon class="section-gap"/>
  <StatePanel :loading="pending&&!data" :error="!data?error:''" :empty="false" @retry="state.refresh">
   <template v-if="data">
    <div class="overview-metrics"><a-button v-for="metric in metrics" :key="metric.label" :class="['overview-metric',metric.tone]" @click="metric.path==='/alerts'?alerts():router.push(metric.path)"><span>{{metric.label}}</span><strong :title="metric.value">{{countText(metric.value)}}</strong><small>查看记录 →</small></a-button></div>
    <p class="muted overview-observation">统计范围：{{formatTime(data.window.start)}} — {{formatTime(data.window.end)}} · 观测时间：{{formatTime(data.observed_at)}} · 探针状态为当前状态</p>
    <a-alert v-if="data.events.total==='0'" type="info" message="该时间范围内暂无已索引告警，请核对监测范围与采集状态。" show-icon class="section-gap"/>
    <div class="overview-grid"><section class="panel overview-wide"><div class="panel-header"><h2>告警趋势</h2><span>{{data.events.interval==='day'?'按天':'按小时'}} · UTC</span></div><OverviewChart :option="trend" :label="trendLabel"/></section><section class="panel"><div class="panel-header"><h2>告警级别</h2><a-button type="link" size="small" @click="show('告警级别',data.events.severity)">查看分布</a-button></div><div class="overview-severities"><div v-for="b in data.events.severity.buckets" :key="b.key"><div class="distribution-label"><span>{{severityName[b.key]??b.key}}</span><strong :title="b.count">{{countText(b.count)}}</strong></div><a-progress :percent="percentage(b.count,data.events.total)" :show-info="false" :stroke-color="b.key==='high'?'#e83855':b.key==='medium'?'#cd7100':b.key==='low'?'#096bff':'#6d83a5'"/></div><p v-if="!data.events.severity.buckets.length" class="muted">暂无告警级别数据</p></div></section><section class="panel"><div class="panel-header"><h2>协议分布</h2><a-button type="link" size="small" @click="show('协议分布',data.events.protocols)">查看分布</a-button></div><OverviewChart v-if="data.events.protocols.buckets.length" :option="protocolOption" :label="distributionLabel('协议 Top 10 分布',data.events.protocols)"/><p v-else class="muted overview-empty">暂无协议数据</p></section><section class="panel"><div class="panel-header"><h2>规则命中分布</h2><a-button type="link" size="small" @click="show('规则命中分布',data.events.rules)">查看分布</a-button></div><OverviewChart v-if="data.events.rules.buckets.length" :option="ruleOption" :label="distributionLabel('规则 Top 10 分布',data.events.rules)"/><p v-else class="muted overview-empty">暂无规则命中数据</p></section><section class="panel"><div class="panel-header"><h2>监测范围</h2><a-button type="link" size="small" @click="show('探针告警分布',data.events.sensors)">探针告警分布</a-button></div><dl class="overview-scope"><div><dt>已登记资产组</dt><dd>{{countText(data.inventory.groups)}}</dd></div><div><dt>已登记网段</dt><dd>{{countText(data.inventory.networks)}}</dd></div><div><dt>已登记探针</dt><dd>{{countText(data.inventory.sensors)}}</dd></div><div><dt>已停用探针</dt><dd>{{countText(data.inventory.disabled)}}</dd></div></dl></section></div>
    <a-collapse class="section-gap"><a-collapse-panel key="limits" header="统计口径与观测限制"><ul><li v-for="limit in data.limitations" :key="limit">{{limit}}</li></ul><p>图形使用近似数值展示趋势；分布详情保留完整整数计数。</p></a-collapse-panel></a-collapse>
   </template>
  </StatePanel>
  <a-modal :open="!!detail" :title="detailTitle" :footer="null" :width="620" @cancel="detail=null"><template v-if="detail"><p class="muted">其他：{{countText(detail.other)}} · 分布误差上界：{{countText(detail.error_upper_bound)}}</p><div class="table-wrap"><a-table :data-source="[...detail.buckets]" :columns="[{title:'分布项',dataIndex:'key'},{title:'告警数',dataIndex:'count'}]" row-key="key" :pagination="false" :scroll="{x:420}"/></div></template></a-modal>
 </main>
</template>
<style scoped>
.overview-workspace{min-width:0}.overview-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.overview-metric.ant-btn{height:auto;min-height:114px;white-space:normal;text-align:left;padding:16px;border-color:var(--line);border-top:3px solid var(--primary);display:flex;flex-direction:column;align-items:flex-start;gap:6px;color:var(--text);background:white}.overview-metric strong{font-size:28px;line-height:1.3;overflow-wrap:anywhere}.overview-metric small{color:var(--muted)}.overview-metric.violet{border-top-color:#8950e9}.overview-metric.green{border-top-color:#079454}.overview-metric.amber{border-top-color:#cd7100}.overview-observation{font-size:12px;margin:8px 0;overflow-wrap:anywhere}.overview-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.overview-wide{grid-column:span 2}.overview-grid .panel{min-width:0}.overview-severities{padding:12px;display:grid;gap:12px}.distribution-label{display:flex;justify-content:space-between;gap:8px}.overview-scope{margin:12px 0;display:grid;gap:14px}.overview-scope>div{display:flex;justify-content:space-between;gap:12px}.overview-scope dd{margin:0;font-weight:600}.overview-empty{min-height:180px;display:grid;place-items:center}.overview-screen{background:var(--workspace);padding:16px}.overview-screen:fullscreen{overflow:auto}.overview-screen .overview-chart{height:280px}@media(min-width:1920px){.overview-screen .overview-grid{gap:16px}.overview-screen .overview-chart{height:340px}}@media(max-width:1180px){.overview-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-wide{grid-column:span 2}}@media(max-width:820px){.overview-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-grid{grid-template-columns:minmax(0,1fr)}.overview-wide{grid-column:auto}.overview-screen{padding:8px}}@media(prefers-reduced-motion:reduce){.overview-metric{transition:none}}
</style>
